"""L10M-ORACLE-3 conservative, target-driven closed-loop policy."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Apply safety gating, confidence hysteresis, bounded reacquisition, and steering control."""
    memory = dict(memory or {})

    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_ticks = int(memory.get("scan_ticks", 0))
    last_action = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = float(observation["heading_error"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        memory["scan_ticks"] = scan_ticks
        return action, confidence, memory

    # Safety is an unconditional gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    # Require a confirmed target before making progress.  On loss, hold once,
    # then scan in a direction long enough to avoid frame-to-frame oscillation.
    confirmed = visible and target_confidence >= 0.55 and identity_confidence >= 0.60
    if not confirmed:
        if lost_steps <= 1 and state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"}:
            return emit("STOP", 0.93, "REACQUIRE")

        scan_ticks += 1
        if scan_ticks >= 2:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            scan_ticks = 0
        memory["scan_direction"] = scan_direction
        memory["scan_ticks"] = scan_ticks
        return emit(scan_direction, 0.76, "SEARCH")

    scan_ticks = 0
    memory["scan_ticks"] = 0
    memory["scan_direction"] = scan_direction

    # Newly acquired tracks are stabilized before forward motion.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.82, "VERIFY")

    # Near-target arrival requires both alignment and strong identity confidence.
    if distance == "near":
        if abs(heading_error) <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")

        turn_error = bearing if abs(bearing) >= 8.0 else heading_error
        if turn_error < 0:
            return emit("VEER_LEFT", 0.89, "APPROACH")
        if turn_error > 0:
            return emit("VEER_RIGHT", 0.89, "APPROACH")
        return emit("SLOW_DOWN", 0.84, "APPROACH")

    # Use a modest deadband for efficient progress, with corridor checks before
    # every directional or forward command.
    if bearing < -14.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if bearing > 14.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.90, "APPROACH")

    if observation["corridor_center"] and abs(bearing) <= 14.0:
        return emit("FORWARD", 0.91, "APPROACH")

    if bearing < 0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.84, "APPROACH")
    if bearing > 0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.84, "APPROACH")

    # If the preferred side is unavailable, retain a safe previous turn when
    # possible; otherwise use whichever visible corridor remains.
    if last_action == "VEER_LEFT" and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.80, "APPROACH")
    if last_action == "VEER_RIGHT" and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.80, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.80, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.80, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
